#[cfg(test)]
mod tests {
    use super::*;

    fn close(a: f64, b: f64) -> bool {
        (a - b).abs() < 1e-9
    }

    #[test]
    fn circle() {
        let c = Shape::Circle { r: 2.0 };
        assert!(close(c.area(), std::f64::consts::PI * 4.0));
        assert!(close(c.perimeter(), std::f64::consts::PI * 4.0));
    }

    #[test]
    fn rect() {
        let r = Shape::Rect { w: 3.0, h: 4.0 };
        assert!(close(r.area(), 12.0));
        assert!(close(r.perimeter(), 14.0));
    }

    #[test]
    fn triangle() {
        let t = Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 };
        assert!(close(t.area(), 6.0));
        assert!(close(t.perimeter(), 12.0));
    }

    #[test]
    fn validity() {
        assert!(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.is_valid());
        assert!(!Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 }.is_valid());
        assert!(!Shape::Circle { r: 0.0 }.is_valid());
        assert!(!Shape::Rect { w: -1.0, h: 2.0 }.is_valid());
        assert!(Shape::Rect { w: 1.0, h: 2.0 }.is_valid());
    }
}
